INSERT INTO listings (id,destination_id,type,name,location_text,description,rating_avg,review_count,price_from,amenities,map_query,hero_image_key) VALUES
(13,1,'hotel','Patong Bay Residence','หาดป่าตอง ภูเก็ต','Patong Bay Residence ที่พักคุณภาพที่หาดป่าตอง ภูเก็ต จุดเด่น: สระว่ายน้ำ · Wi-Fi · ฟิตเนส ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.5,720,2400,'["สระว่ายน้ำ", "Wi-Fi", "ฟิตเนส"]','Patong Bay Residence หาดป่าตอง ภูเก็ต','seed/listing-13.jpg'),
(14,1,'restaurant','โอเชียนเทอเรซ ซีฟู้ด','หาดกะรน ภูเก็ต','โอเชียนเทอเรซ ซีฟู้ด ร้านอาหารแนะนำที่หาดกะรน ภูเก็ต จุดเด่น: วิวทะเล · อาหารทะเลสด · รับจองโต๊ะ ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.6,410,890,'["วิวทะเล", "อาหารทะเลสด", "รับจองโต๊ะ"]','โอเชียนเทอเรซ ซีฟู้ด หาดกะรน ภูเก็ต','seed/listing-14.jpg'),
(15,1,'attraction','ดำน้ำตื้นเกาะราชา','ท่าเรือฉลอง ภูเก็ต','ดำน้ำตื้นเกาะราชา กิจกรรมยอดนิยมที่ท่าเรือฉลอง ภูเก็ต จุดเด่น: อุปกรณ์ดำน้ำ · อาหารกลางวัน · ไกด์ ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.7,640,1650,'["อุปกรณ์ดำน้ำ", "อาหารกลางวัน", "ไกด์"]','ดำน้ำตื้นเกาะราชา ท่าเรือฉลอง ภูเก็ต','seed/listing-15.jpg'),
(16,2,'hotel','Doi Suthep Hillside Lodge','สุเทพ เชียงใหม่','Doi Suthep Hillside Lodge ที่พักคุณภาพที่สุเทพ เชียงใหม่ จุดเด่น: วิวภูเขา · อาหารเช้า · Wi-Fi ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.6,305,2200,'["วิวภูเขา", "อาหารเช้า", "Wi-Fi"]','Doi Suthep Hillside Lodge สุเทพ เชียงใหม่','seed/listing-16.jpg'),
(17,2,'restaurant','เฮือนเจ้านาง','ในเมือง เชียงใหม่','เฮือนเจ้านาง ร้านอาหารแนะนำที่ในเมือง เชียงใหม่ จุดเด่น: อาหารล้านนา · บรรยากาศดั้งเดิม ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.7,520,380,'["อาหารล้านนา", "บรรยากาศดั้งเดิม"]','เฮือนเจ้านาง ในเมือง เชียงใหม่','seed/listing-17.jpg'),
(18,2,'attraction','ปางช้างจริยธรรม','แม่แตง เชียงใหม่','ปางช้างจริยธรรม กิจกรรมยอดนิยมที่แม่แตง เชียงใหม่ จุดเด่น: ไม่ขี่ช้าง · อาหารกลางวัน · รถรับส่ง ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.9,1180,2300,'["ไม่ขี่ช้าง", "อาหารกลางวัน", "รถรับส่ง"]','ปางช้างจริยธรรม แม่แตง เชียงใหม่','seed/listing-18.jpg'),
(19,3,'attraction','ทัวร์ 4 เกาะ ทะเลแหวก','อ่าวนาง กระบี่','ทัวร์ 4 เกาะ ทะเลแหวก กิจกรรมยอดนิยมที่อ่าวนาง กระบี่ จุดเด่น: เรือหางยาว · อุปกรณ์ดำน้ำ · อาหารกลางวัน ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.7,890,1100,'["เรือหางยาว", "อุปกรณ์ดำน้ำ", "อาหารกลางวัน"]','ทัวร์ 4 เกาะ ทะเลแหวก อ่าวนาง กระบี่','seed/listing-19.jpg'),
(20,3,'restaurant','ครัวอ่าวนาง','อ่าวนาง กระบี่','ครัวอ่าวนาง ร้านอาหารแนะนำที่อ่าวนาง กระบี่ จุดเด่น: อาหารใต้ · ราคาประหยัด ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.4,260,520,'["อาหารใต้", "ราคาประหยัด"]','ครัวอ่าวนาง อ่าวนาง กระบี่','seed/listing-20.jpg'),
(21,4,'hotel','Sukhumvit Urban Suites','สุขุมวิท กรุงเทพฯ','Sukhumvit Urban Suites ที่พักคุณภาพที่สุขุมวิท กรุงเทพฯ จุดเด่น: ใกล้ BTS · สระว่ายน้ำ · Co-working ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.5,1320,2900,'["ใกล้ BTS", "สระว่ายน้ำ", "Co-working"]','Sukhumvit Urban Suites สุขุมวิท กรุงเทพฯ','seed/listing-21.jpg'),
(22,4,'attraction','ล่องเรือเจ้าพระยาพร้อมมื้อค่ำ','ท่าเรือ ICONSIAM กรุงเทพฯ','ล่องเรือเจ้าพระยาพร้อมมื้อค่ำ กิจกรรมยอดนิยมที่ท่าเรือ ICONSIAM กรุงเทพฯ จุดเด่น: บุฟเฟต์ · วิวพระบรมมหาราชวัง ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.6,1750,1290,'["บุฟเฟต์", "วิวพระบรมมหาราชวัง"]','ล่องเรือเจ้าพระยาพร้อมมื้อค่ำ ท่าเรือ ICONSIAM กรุงเทพฯ','seed/listing-22.jpg'),
(23,4,'flight','BKK → CNX บินตรง','สุวรรณภูมิ → เชียงใหม่','BKK → CNX บินตรง เที่ยวบินตรงที่สุวรรณภูมิ → เชียงใหม่ จุดเด่น: ตรงเวลา · น้ำหนักกระเป๋า 20 กก. ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.5,410,1450,'["ตรงเวลา", "น้ำหนักกระเป๋า 20 กก."]','BKK → CNX บินตรง สุวรรณภูมิ → เชียงใหม่','seed/listing-23.jpg'),
(24,4,'flight','DMK → KBV บินตรง','ดอนเมือง → กระบี่','DMK → KBV บินตรง เที่ยวบินตรงที่ดอนเมือง → กระบี่ จุดเด่น: ราคาประหยัด · อาหารบนเครื่อง ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.3,230,1290,'["ราคาประหยัด", "อาหารบนเครื่อง"]','DMK → KBV บินตรง ดอนเมือง → กระบี่','seed/listing-24.jpg'),
(25,5,'hotel','Chaweng Palm Resort','หาดเฉวง เกาะสมุย','Chaweng Palm Resort ที่พักคุณภาพที่หาดเฉวง เกาะสมุย จุดเด่น: ติดชายหาด · สระว่ายน้ำ · สปา ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.6,680,3600,'["ติดชายหาด", "สระว่ายน้ำ", "สปา"]','Chaweng Palm Resort หาดเฉวง เกาะสมุย','seed/listing-25.jpg'),
(26,5,'attraction','ทัวร์อ่างทอง 1 วัน','เกาะสมุย','ทัวร์อ่างทอง 1 วัน กิจกรรมยอดนิยมที่เกาะสมุย จุดเด่น: เรือสปีดโบ๊ท · พายคายัค · อาหารกลางวัน ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.8,540,1850,'["เรือสปีดโบ๊ท", "พายคายัค", "อาหารกลางวัน"]','ทัวร์อ่างทอง 1 วัน เกาะสมุย','seed/listing-26.jpg'),
(27,6,'hotel','Pai Riverside Bungalows','ริมน้ำปาย แม่ฮ่องสอน','Pai Riverside Bungalows ที่พักคุณภาพที่ริมน้ำปาย แม่ฮ่องสอน จุดเด่น: ริมแม่น้ำ · อาหารเช้า · Wi-Fi ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.7,330,1500,'["ริมแม่น้ำ", "อาหารเช้า", "Wi-Fi"]','Pai Riverside Bungalows ริมน้ำปาย แม่ฮ่องสอน','seed/listing-27.jpg'),
(28,6,'trip','แพ็กเกจปาย 3 วัน 2 คืน','ปาย แม่ฮ่องสอน','แพ็กเกจปาย 3 วัน 2 คืน แพ็กเกจเที่ยวครบ จบในเที่ยวเดียวที่ปาย แม่ฮ่องสอน จุดเด่น: ที่พัก 2 คืน · รถตู้ · ทัวร์น้ำตก ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.6,145,5600,'["ที่พัก 2 คืน", "รถตู้", "ทัวร์น้ำตก"]','แพ็กเกจปาย 3 วัน 2 คืน ปาย แม่ฮ่องสอน','seed/listing-28.jpg'),
(29,7,'trip','แพ็กเกจอยุธยา วันเดียว','อยุธยา','แพ็กเกจอยุธยา วันเดียว แพ็กเกจเที่ยวครบ จบในเที่ยวเดียวที่อยุธยา จุดเด่น: รถรับส่ง · ไกด์ · ค่าเข้าชม ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.5,260,1250,'["รถรับส่ง", "ไกด์", "ค่าเข้าชม"]','แพ็กเกจอยุธยา วันเดียว อยุธยา','seed/listing-29.jpg'),
(30,8,'hotel','Khao Yai Vineyard Stay','ปากช่อง นครราชสีมา','Khao Yai Vineyard Stay ที่พักคุณภาพที่ปากช่อง นครราชสีมา จุดเด่น: วิวไร่องุ่น · อาหารเช้า · สระส่วนตัว ยกเลิกฟรีตามเงื่อนไขของรายการ ยืนยันทันทีผ่านแอป',4.8,410,4800,'["วิวไร่องุ่น", "อาหารเช้า", "สระส่วนตัว"]','Khao Yai Vineyard Stay ปากช่อง นครราชสีมา','seed/listing-30.jpg');
INSERT INTO faqs (question,answer,sort_no) VALUES
('เปลี่ยนวันเดินทางได้หรือไม่?','ได้ หากรายการนั้นอนุญาต ไปที่ การจองของฉัน > รายละเอียด แล้วติดต่อทีมงานเพื่อแก้ไขวันที่',4),
('คูปองใช้ร่วมกันได้หรือไม่?','ใช้ได้ครั้งละ 1 คูปองต่อ 1 การจอง และต้องมียอดขั้นต่ำตามเงื่อนไขของคูปอง',5),
('เงินคืนเข้ากระเป๋าเมื่อไร?','เงินคืนเข้า Wallet ทันทีเมื่อการยกเลิกได้รับการยืนยัน',6),
('ลืมรหัสผ่านต้องทำอย่างไร?','ไปที่ โปรไฟล์ > ความปลอดภัย > เปลี่ยนรหัสผ่าน หรือติดต่อทีมงานผ่านหน้า ติดต่อเรา',7),
('ใบกำกับภาษีขอได้ที่ไหน?','ส่งคำขอผ่านหน้า ติดต่อเรา ระบุเลขที่การจอง ทีมงานจะดำเนินการภายใน 3 วันทำการ',8),
('ข้อมูลส่วนตัวถูกใช้อย่างไร?','เราใช้ข้อมูลเพื่อให้บริการจองและปรับปรุงประสบการณ์เท่านั้น อ่านรายละเอียดได้ที่นโยบายความเป็นส่วนตัว',9),
('ลบบัญชีได้หรือไม่?','ได้ที่ ตั้งค่า > ลบบัญชี ข้อมูลส่วนบุคคลจะถูกทำให้ไม่ระบุตัวตน',10),
('จองให้ผู้อื่นได้หรือไม่?','ได้ ระบุจำนวนผู้เดินทางตอนจอง และแสดงเลขที่การจองเมื่อเช็กอิน',11),
('PromptPay ชำระภายในกี่นาที?','QR มีอายุ 15 นาที หากหมดอายุสามารถสร้างรายการชำระใหม่ได้',12),
('Wallet มีวันหมดอายุหรือไม่?','ยอดเงินใน Wallet ไม่มีวันหมดอายุ',13),
('สมัครเป็นพาร์ทเนอร์อย่างไร?','ไปที่ เมนู > สมัครเป็นพาร์ทเนอร์ กรอกข้อมูลธุรกิจ ทีมงานจะพิจารณาภายใน 2 วันทำการ',14),
('ค่าคอมมิชชันพาร์ทเนอร์เท่าไร?','ค่าเริ่มต้น 12% ของยอดรายการ ปรับได้ตามที่แอดมินกำหนด',15),
('รีวิวเขียนได้เมื่อใด?','เขียนรีวิวได้หลังการจองเสร็จสิ้น 1 ครั้งต่อรายการ',16),
('ติดต่อฉุกเฉินระหว่างเดินทาง?','ใช้หน้า ติดต่อเรา เลือกหัวข้อเร่งด่วน หรือโทรสายด่วน 1155 สำหรับตำรวจท่องเที่ยว',17),
('AI วางแผนทริปแม่นยำแค่ไหน?','เป็นข้อเสนอแนะเบื้องต้น ควรตรวจสอบเวลาเปิดปิดและราคาก่อนเดินทาง',18),
('ใช้แอปได้กี่ภาษา?','รองรับภาษาไทยและอังกฤษ ตั้งค่าได้ที่ ตั้งค่า > ภาษา',19);
